// ── Union-Find (Disjoint Set Union) ───────────────────────────
class UnionFind {
  constructor(n) {
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.rank = new Array(n).fill(0);
  }
  find(x) {
    if (this.parent[x] !== x)
      this.parent[x] = this.find(this.parent[x]); // path compression
    return this.parent[x];
  }
  union(x, y) {
    const px = this.find(x), py = this.find(y);
    if (px === py) return false; // already same component
    // union by rank
    if (this.rank[px] < this.rank[py]) this.parent[px] = py;
    else if (this.rank[px] > this.rank[py]) this.parent[py] = px;
    else { this.parent[py] = px; this.rank[px]++; }
    return true;
  }
}

// ── Kruskal's Algorithm — O(E log E) ──────────────────────────
// edges: array of [u, v, weight] (0-indexed vertices)
function kruskal(numVertices, edges) {
  edges.sort((a, b) => a[2] - b[2]); // sort by weight
  const uf = new UnionFind(numVertices);
  const mstEdges = [];
  let totalWeight = 0;

  for (const [u, v, w] of edges) {
    if (uf.union(u, v)) { // no cycle created
      mstEdges.push([u, v, w]);
      totalWeight += w;
      if (mstEdges.length === numVertices - 1) break; // MST complete
    }
  }
  return { mstEdges, totalWeight };
}

// Graph: A=0, B=1, C=2, D=3
const edges = [
  [0, 1, 1], // A-B weight 1
  [0, 2, 3], // A-C weight 3
  [1, 2, 2], // B-C weight 2
  [1, 3, 4], // B-D weight 4
  [2, 3, 5], // C-D weight 5
];

const { mstEdges, totalWeight } = kruskal(4, edges);
console.log(mstEdges);    // [[0,1,1],[1,2,2],[1,3,4]]
console.log(totalWeight); // 7

// ── Prim's Algorithm — O((V+E) log V) ────────────────────────
// graph: adjacency list { node: [[neighbor, weight], ...] }
function prim(graph, startNode) {
  const inMST = new Set();
  const mstEdges = [];
  let totalWeight = 0;

  // Min-heap: [weight, from, to]
  // Start with all edges from startNode
  let heap = graph[startNode].map(([neighbor, w]) => [w, startNode, neighbor]);
  heap.sort((a, b) => a[0] - b[0]);
  inMST.add(startNode);

  while (heap.length > 0 && mstEdges.length < Object.keys(graph).length - 1) {
    heap.sort((a, b) => a[0] - b[0]);
    const [w, u, v] = heap.shift();

    if (inMST.has(v)) continue; // v already in MST
    inMST.add(v);
    mstEdges.push([u, v, w]);
    totalWeight += w;

    // Add all edges from v to non-MST vertices
    for (const [neighbor, weight] of (graph[v] || [])) {
      if (!inMST.has(neighbor)) {
        heap.push([weight, v, neighbor]);
      }
    }
  }
  return { mstEdges, totalWeight };
}

const g = {
  A: [["B", 1], ["C", 3]],
  B: [["A", 1], ["C", 2], ["D", 4]],
  C: [["A", 3], ["B", 2], ["D", 5]],
  D: [["B", 4], ["C", 5]]
};

const result = prim(g, "A");
console.log(result.mstEdges);    // [['A','B',1],['B','C',2],['B','D',4]]
